/// Connection settings. Copy these from WordPress → AppForge → Settings.
///
/// They can also be passed at build time (used by the GitHub Actions workflow):
///   flutter build apk --dart-define=APPFORGE_BASE_URL=https://yourstore.com/ \
///                     --dart-define=APPFORGE_API_KEY=afk_... --dart-define=APPFORGE_API_SECRET=afs_...
class AppConfig {
  AppConfig._();

  /// Your WordPress site URL.
  static const String baseUrl = String.fromEnvironment('APPFORGE_BASE_URL', defaultValue: 'https://yourdomain.com/');

  /// App API key & secret generated by the AppForge Builder plugin.
  static const String apiKey = String.fromEnvironment('APPFORGE_API_KEY', defaultValue: 'afk_xxxxxxxxxxxxxxxx');
  static const String apiSecret = String.fromEnvironment('APPFORGE_API_SECRET', defaultValue: 'afs_xxxxxxxxxxxxxxxx');

  /// REST namespace of the plugin. Do not change.
  static const String namespace = 'wp-json/appforge/v1';

  static String get apiBase => '${baseUrl.endsWith('/') ? baseUrl : '$baseUrl/'}$namespace';
}
